#pragma once
inline Json previewItems(){Json rows=Json::array();const std::vector<std::string> names={"暮色回响","归来的春天","城市微光","山海之间","一纸星河","最好的重逢","向阳而生","风起长安"};for(size_t i=0;i<names.size();i++)rows.push_back(Json{{"id",std::to_string(1000+i)},{"title",names[i]},{"cover","preview:"+std::to_string(i)},{"badge","共 "+std::to_string(36+i*7)+" 集"},{"tags",i%2?"古装 / 剧情":"都市 / 情感"},{"description","用于检查界面布局的演示数据，不代表线上视频资源。"}});return rows;}
inline Json previewDetail(const std::string& id){auto row=previewItems()[0];row["id"]=id;row["episodes"]=Json::array();for(int i=0;i<138;i++)row["episodes"].push_back(Json{{"id",std::to_string(5000+i)},{"number",i+1},{"title","第 "+std::to_string(i+1)+" 集"},{"localPath","build/preview-video.mp4"}});return row;}
inline Json previewCall(const std::string& function,const Json& args){if(function=="home"||function=="search"){int page=args[function=="home"?0:1].get<int>();Json rows=Json::array();auto sample=previewItems();int start=page==1?0:page==2?16:34,count=page<3?18:page==3?8:0;for(int i=0;i<count;++i){auto row=sample[(start+i)%sample.size()];row["id"]=std::to_string(1000+start+i);row["title"]=row["title"].get<std::string>()+" · "+std::to_string(start+i+1);rows.push_back(row);}return Json{{"items",rows},{"page",page},{"hasMore",page<3}};}if(function=="detail")return previewDetail(args[0].get<std::string>());if(function=="qualities")return Json::array();if(function=="clearCache")return Json{{"entries",0}};return Json::object();}
